    hull = points;
    return hull;
}

// Find the lowest point
Point_2 start = points[0];
for (const auto& p : points) {
    if (p.y() < start.y() || (p.y() == start.y() && p.x() < start.x())) {
        start = p;
    }
}

// Sort points by polar angle with the start point
std::vector<std::pair<Point_2, double>> sorted_points;
for (const auto& p : points) {
    if (p == start) continue;
    double angle = std::atan2(p.y() - start.y(), p.x() - start.x());
    sorted_points.emplace_back(p, angle);
}
std::sort(sorted_points.begin(), sorted_points.end(),
          [](const auto& a, const auto& b) { return a.second < b.second; });

// Initialize an empty stack and push the first three points to it
std::vector<Point_2> stack;
stack.push_back(start);
stack.push_back(sorted_points[0].first);
stack.push_back(sorted_points[1].first);

// Process the rest of the sorted points
for (size_t i = 2; i < sorted_points.size(); ++i) {
    while (stack.size() > 1 && !is_ccw(stack[stack.size() - 2], stack.back(), sorted_points[i].first)) {
        stack.pop_back();
    }
    stack.push_back(sorted_points[i].first);
}

hull = stack;
return hull;

